from collections import OrderedDict

class SegmentedLRU:
    def __init__(self, probation_cap: int, protected_cap: int):
        assert probation_cap > 0 and protected_cap > 0
        self.probation: OrderedDict = OrderedDict()  # key -> value
        self.protected: OrderedDict = OrderedDict()
        self.P = probation_cap
        self.R = protected_cap

    def get(self, key):
        if key in self.protected:
            self.protected.move_to_end(key, last=True)  # MRU at end
            return self.protected[key]
        if key in self.probation:
            val = self.probation.pop(key)
            self._promote(key, val)
            return val
        return None  # miss: caller fetches and calls put()

    def put(self, key, value):
        if key in self.protected:
            self.protected[key] = value
            self.protected.move_to_end(key, last=True)
            return
        if key in self.probation:
            self.probation[key] = value
            self.probation.move_to_end(key, last=True)
            return
        # miss: always admit to probation MRU
        self.probation[key] = value
        self.probation.move_to_end(key, last=True)
        if len(self.probation) > self.P:
            self.probation.popitem(last=False)  # evict probation LRU

    def _promote(self, key, value):
        # make room in protected by demoting its LRU to probation MRU
        if len(self.protected) >= self.R:
            dem_key, dem_val = self.protected.popitem(last=False)
            self.probation[dem_key] = dem_val
            self.probation.move_to_end(dem_key, last=True)
            if len(self.probation) > self.P:
                self.probation.popitem(last=False)
        self.protected[key] = value
        self.protected.move_to_end(key, last=True)
